from __future__ import unicode_literals

import os

import cfnlint.decode.cfn_yaml as cfn_yaml
from cfnlint._typing import RuleMatches
from cfnlint.rules import CloudFormationLintRule, RuleMatch
from cfnlint.template import Template


class Used(CloudFormationLintRule):
    """Check if Parameters are used"""

    id = "W2001"
    shortdesc = "Check if Parameters are Used"
    description = "Making sure the parameters defined are used"
    source_url = "https://github.com/aws-cloudformation/cfn-lint"
    tags = ["parameters"]

    def match(self, cfn: Template) -> RuleMatches:
        matches: RuleMatches = []

        le_refs = None
        if cfn.has_language_extensions_transform():
            le_refs = cfn.search_deep_keys("Ref")

        reftrees = cfn.transform_pre.get("Ref", [])
        subtrees = cfn.transform_pre.get("Fn::Sub", [])
        refs = []
        for reftree in reftrees:
            refs.append(reftree[-1])
        if le_refs:
            for le_ref in le_refs:
                if le_ref[-1] not in refs:
                    refs.append(le_ref[-1])

        subs = []
        for subtree in subtrees:
            if isinstance(subtree[-1], list):
                subs.extend(cfn.get_sub_parameters(subtree[-1][0]))
            elif isinstance(subtree[-1], str):
                subs.extend(cfn.get_sub_parameters(subtree[-1]))

        # Handle parameters referenced in files included via Fn::Transform/AWS::Include
        # The included content is not part of the template tree, so scan the included file(s)
        # for Ref and Fn::Sub usages and treat those parameters as used.
        transform_usages = cfn.search_deep_keys("Fn::Transform")
        for t_usage in transform_usages:
            transform_value = t_usage[-1]
            if not isinstance(transform_value, dict):
                continue
            if transform_value.get("Name") != "AWS::Include":
                continue
            parameters = transform_value.get("Parameters", {})
            location = parameters.get("Location")
            # Only handle local file include paths as strings
            if not isinstance(location, str):
                continue
            # Resolve location relative to template path, if necessary
            base_dir = os.path.dirname(cfn.filename or "")
            include_path = (
                location
                if os.path.isabs(location)
                else os.path.normpath(os.path.join(base_dir, location))
            )
            try:
                include_template = cfn_yaml.load(include_path)
            except Exception:  # pylint: disable=broad-except
                include_template = None
            if not include_template:
                continue
            try:
                included_cfn = Template(include_path, include_template, cfn.regions)
            except Exception:  # pylint: disable=broad-except
                included_cfn = None
            if not included_cfn:
                continue
            # Gather Refs from included content
            for reftree in included_cfn.search_deep_keys("Ref"):
                ref_name = reftree[-1]
                if isinstance(ref_name, str) and ref_name not in refs:
                    refs.append(ref_name)
            # Gather Sub parameters from included content
            for subtree in included_cfn.search_deep_keys("Fn::Sub"):
                sub_value = subtree[-1]
                if isinstance(sub_value, list) and sub_value:
                    subs.extend(included_cfn.get_sub_parameters(sub_value[0]))
                elif isinstance(sub_value, str):
                    subs.extend(included_cfn.get_sub_parameters(sub_value))

        for paramname in cfn.template.get("Parameters", {}).keys():
            if paramname not in refs:
                if paramname not in subs:
                    message = "Parameter {0} not used."
                    matches.append(
                        RuleMatch(["Parameters", paramname], message.format(paramname))
                    )

        return matches

